<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class Cart extends HRC_Controller {	public function __construct()	{		parent::__construct();		$this->load->library('cart');	}	public function index()	{		$data['page'] = 'cart';		$data['currency'] = $this->currency;		$data['menus'] = $this->mainMenu();		$data['products'] = $this->cart->contents();		$data['total'] = $this->cart->total();		$this->load->view('pages/cart/cart', $data);	}	public function information()	{		if(is_null($this->session->cart_contents))		{			redirect(base_url('malaysia-furniture-promotions'));		}		$data['countries'] = Country::lists('name', 'id');		$data['menus'] = $this->mainMenu();				$data['page'] = __FUNCTION__;		$this->load->view('pages/cart/information', $data);	}	public function add()	{		if(!check_ajax())		{			show_404();		}				$data['page'] = 'cart';		if ($this->input->post('qty') < 1)		{			echo false;			return;		}		$size = ProductSize::find($this->input->post('size_id'));		$products = [			'id'		=> $size->id,			'name'	=> $size->product->name,			'code'	=> $size->product->code,			'dimension'	=> $size->product->dimension,			'image'	=> is_null($size->product->imageThumb['name']) ? 'not-available.jpg' : $size->product->imageThumb['name'],			'size'	=> $size->name,			'qty' 	=> $this->input->post('qty'),			'price'	=> $size->prices->is_promo ? $size->prices->promo : $size->prices->normal,		];		if ($this->cart->insert($products))		{			$carts = [];			$carts['contents'] = $this->cart->contents();			$carts['total'] = $this->cart->total();			$carts['total_items'] = $this->cart->total_items();			echo json_encode($carts);		}				return  false;	}	public function update()	{		if($this->input->post('action') != 'update')		{			show_404();		}		$data = json_decode($this->input->post('data'), true);		echo $this->cart->update($data);	}	public function remove()	{		if($this->input->post('action') != 'remove')		{			show_404();		}		echo $this->cart->remove($this->input->post('id'));	}	public function destroy()	{		$this->cart->destroy();	}}/* End of file cart.php *//* Location: ./application/controllers/cart.php */